const { text } = input;
if (typeof text !== 'string') {
  throw new Error('Missing or invalid "text" input');
}
globalThis.text = text;

const PDFKit = await import('pdfkit');
const PDFDocument = PDFKit.default || PDFKit;
let chunks = [];
const doc = new PDFDocument();
await new Promise((resolve, reject) => {
  doc.on('data', (c) => chunks.push(c));
  doc.on('end', () => {
    const buffer = Buffer.concat(chunks);
    globalThis.pdf_base64 = buffer.toString('base64');
    resolve();
  });
  doc.on('error', reject);
  doc.text(globalThis.text);
  doc.end();
});

if (!globalThis.pdf_base64) {
  throw new Error('PDF generation failed, no output');
}
console.log(JSON.stringify({ pdf_base64: globalThis.pdf_base64 }));
